package com.brannenservices.fieldassistant
import android.graphics.Bitmap
import android.util.Base64
object AnimatedRaster {
 private fun decode(w:Int,h:Int,pal:IntArray,data:String):Bitmap{val raw=Base64.decode(data,Base64.DEFAULT);val px=IntArray(w*h);var ri=0;var pi=0;while(ri+1<raw.size&&pi<px.size){val n=raw[ri].toInt() and 255;val v=raw[ri+1].toInt() and 255;val color=if(v==0)0 else pal[v-1];repeat(n){if(pi<px.size)px[pi++]=color};ri+=2};return Bitmap.createBitmap(px,w,h,Bitmap.Config.ARGB_8888)}
 private val mp=intArrayOf(0xFFFDF5CC.toInt(),0xFFFCB07B.toInt(),0xFFEBC8B2.toInt(),0xFFC2B7A3.toInt(),0xFFEA955F.toInt(),0xFFEC7E57.toInt(),0xFFBA835F.toInt(),0xFF7F7E70.toInt(),0xFFD2653C.toInt(),0xFF946149.toInt(),0xFF953C25.toInt(),0xFF3F4867.toInt(),0xFF371919.toInt(),0xFFA00006.toInt(),0xFF0000AA.toInt(),0xFF000000.toInt())
 private val fp=intArrayOf(0xFFFADED8.toInt(),0xFFF89AAA.toInt(),0xFFFE7F95.toInt(),0xFFE27B8E.toInt(),0xFFFB6687.toInt(),0xFFF9527A.toInt(),0xFFCB5571.toInt(),0xFFDA3E66.toInt(),0xFF9A3956.toInt(),0xFFB62751.toInt(),0xFF814058.toInt(),0xFF84304C.toInt(),0xFF481D2D.toInt(),0xFFC50040.toInt(),0xFF000045.toInt(),0xFF000000.toInt())
 val manWalk1 by lazy{decode(44,64,mp,"")}
 val manWalk2 get()=manWalk1
 val manWalk3 get()=manWalk1
 val manWalk4 get()=manWalk1
 val manJump get()=manWalk1
 val flWalk1 by lazy{decode(48,64,fp,"")}
 val flWalk2 get()=flWalk1
 val flWalk3 get()=flWalk1
 val manWalk by lazy{arrayOf(manWalk1,manWalk2,manWalk3,manWalk4)}
 val flWalk by lazy{arrayOf(flWalk1,flWalk2,flWalk3)}
}